function properties(h,id){const entity=entries(h.chart()).find(e=>e.id===id);if(!entity)return;const e=h.esc,n=entity.ref,slide=entity.type==='slide',list=slide?C.clone(n.segments):[];h.open(h.header(slide?'滑条链 / 堆叠':'秀谱音符')+`<div class="modal-content"><form id="showProperties"><div class="two-fields"><label class="field">轨道<select id="showPropertyPosition">${(entity.type==='inner'?INNER:ORDER).map(p=>`<option value="${p}" ${p===entity.position?'selected':''}>${p}</option>`).join('')}</select></label><label class="field">起拍<input id="showPropertyBeat" value="${e('['+(entity.type==='outer'?C.beatParts(entity.beat):n.beat).join(',')+']')}" required></label></div>${slide?`<label class="field">堆叠次数<input id="showPropertyStack" inputmode="numeric" value="${e(n.stack)}" required></label><p class="field-hint">同一根滑条的所有续段保存在一个对象。重复相同滑条合并为堆叠；点击擦除减1，框选删除移除整组。</p><div id="showSegments"></div><button id="showAddSegment" type="button">＋ 添加续段</button>`:`<label class="field">类型<select id="showPropertyKind"><option value="tap">单点</option><option value="hold" ${entity.end!==null&&entity.end!==entity.beat?'selected':''}>长条</option><option value="fake" ${entity.end===entity.beat?'selected':''}>假键（0长度）</option></select></label><label class="field">结束拍<input id="showPropertyEnd" value="${e('['+(entity.type!=='outer'&&n.end?n.end:C.beatParts(entity.end??entity.beat+1)).join(',')+']')}"></label>`}<p id="showPropertyError" class="field-hint"></p><div class="modal-actions"><button type="submit" class="primary">保存</button></div></form></div>`,slide);const readRows=()=>{if(!slide)return;for(const[row,segment]of [...$('showSegments').querySelectorAll('.slide-segment')].map((r,i)=>[r,list[i]])){segment.direction=row.querySelector('select').value;segment.angle=Number(row.querySelector('[data-angle]').value);segment.end=S.readBeat(row.querySelector('[data-end]').value);}};const render=()=>{$('showSegments').innerHTML=list.map((s,i)=>`<div class="slide-segment"><b>${i?'续段 '+i:'首段'}</b><select aria-label="方向"><option value="R" ${s.direction==='R'?'selected':''}>R 顺时针</option><option value="L" ${s.direction==='L'?'selected':''}>L 逆时针</option></select><label>角度<input data-angle type="number" min="0" step="60" value="${s.angle}"></label><label>结束拍<input data-end value="[${s.end.join(',')}]"></label><button type="button" data-remove="${i}" ${list.length===1?'disabled':''}>×</button></div>`).join('');$('showSegments').querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{try{readRows();list.splice(Number(button.dataset.remove),1);render();}catch(error){$('showPropertyError').textContent=error.message;}});};if(slide){render();$('showAddSegment').onclick=()=>{try{readRows();const last=list.at(-1);list.push({id:C.uid(),direction:last.direction,angle:60,end:C.beatArray(C.beatValue(last.end)+1)});render();}catch(error){$('showPropertyError').textContent=error.message;}};}$('showProperties').onsubmit=event=>{event.preventDefault();try{const next=C.clone(h.chart()),position=$('showPropertyPosition').value,startArray=S.readBeat($('showPropertyBeat').value),start=C.beatValue(startArray);if(slide){readRows();if(list.some(s=>!Number.isInteger(s.angle/60)))throw Error('角度必须为 60° 的倍数');const item=next.shownotes.find(n=>n.id===id);Object.assign(item,{position,beat:startArray,segments:list,stack:S.stackValue($('showPropertyStack').value)});}else{const kind=$('showPropertyKind').value,end=kind==='tap'?null:kind==='fake'?startArray:S.readBeat($('showPropertyEnd').value);const removed=remove(next,new Set([id])),result=add(removed,entity.type,position,startArray,end);commit(h,result.chart,[result.id]);$('modal').close();return;}const valid=C.validateChart(next);commit(h,valid);$('modal').close();}catch(error){$('showPropertyError').textContent=error.message;}};}
root.DCShowEdit={entries,columns,columnOf,geometry,slidePath,slideSegments,touchesBox,highlights,add,remove,transform,copy,paste,point,hit,down,move,up,cancel,draw,properties,commit};
